import api from './client';

export const deviceQueryDefaults = {
  page: 1,
  pageSize: 100,
  status: '',
  farmId: '',
};

export async function listDevices(params = {}) {
  return api.get('/devices', {
    params: { ...deviceQueryDefaults, ...params },
  });
}

export function normalizeDeviceQuery(query) {
  return { ...deviceQueryDefaults, ...query };
}
